const b = $json.body || {};
let invalid = false;
if (b.v !== 1) invalid = true;
if (typeof b.chatId !== 'string' || !b.chatId) invalid = true;
if (!Array.isArray(b.messages) || b.messages.length === 0) invalid = true;

let messages = Array.isArray(b.messages) ? b.messages : [];
messages = messages.slice(-24).map(m => ({
  role: (m && m.role === 'client') ? 'client' : 'business',
  text: String((m && m.text) || '').slice(0, 500),
  ts: (m && typeof m.ts === 'number') ? m.ts : 0
}));

const ownerPrompt = String(b.ownerPrompt || '').slice(0, 2000);
const catalog = String(b.catalog || '').slice(0, 2500);
const businessKnowledge = String(b.businessKnowledge || '').slice(0, 1200);
// `now` reaches the SYSTEM prompt (ВРЕМЯ rule) — whitelist-sanitize: the webhook is unauthenticated.
const now = String(b.now || '').replace(/[^0-9A-Za-z\u0400-\u04FF:,. \-]/g, '').slice(0, 64);
const pickStats = String(b.pickStats || '').replace(/[^0-9\u0400-\u04FF:, ]/g, '').slice(0, 200);
const businessName = String(b.businessName || '');
const businessTypeId = String(b.businessTypeId || '');
const botWaId = (typeof b.botWaId === 'string') ? b.botWaId : ''; const channel = (b.channel === 'telegram') ? 'telegram' : 'whatsapp'; const botTgId = (typeof b.botTgId === 'string') ? b.botTgId : '';
const steerTowardText = (b.steerTowardText === null || b.steerTowardText === undefined)
  ? null : String(b.steerTowardText).slice(0, 500);
const lastIncomingText = (b.lastIncomingText === null || b.lastIncomingText === undefined)
  ? null : String(b.lastIncomingText);

// Burst-combine (BATCH-03 gap fix): anchor RAG + lastClientMessage on the whole trailing
// client run (consecutive client messages since the last owner/bot reply), not only the
// final fragment — mirrors the reply path's Latest+Combine run-walk semantics.
const runParts = [];
for (let i = messages.length - 1; i >= 0; i--) {
  const m = messages[i];
  if (m.role !== 'client') break;
  if (m.text && m.text.trim()) runParts.unshift(m.text.trim());
}
// Per-line merge: lastIncomingText now carries the client's WHOLE accumulated burst
// (possibly multi-line) — append each line not already present in the trailing run.
if (lastIncomingText && lastIncomingText.trim()) {
  const seen = new Set(runParts);
  for (const rawLine of lastIncomingText.split('\n')) {
    const line = rawLine.trim();
    if (line && !seen.has(line)) { runParts.push(line); seen.add(line); }
  }
}
let queryText = runParts.join('\n').slice(0, 500);

const wfId = (channel === 'telegram') ? botTgId : botWaId; const skipRag = (wfId === '' || wfId === '-1' || !queryText);
const requestSeq = (b.requestSeq === undefined || b.requestSeq === null) ? 0 : b.requestSeq;

return [{ json: {
  v: 1, requestSeq, invalid,
  profileId: String(b.profileId || ''),
  chatId: String(b.chatId || ''),
  botWaId, botTgId, channel, businessTypeId, businessName, ownerPrompt, catalog, businessKnowledge, now, pickStats,
  steerTowardText, lastIncomingText, messages, queryText, skipRag
} }];

const p = $('Prep').first().json;

let ragChunks = '';
if (!p.skipRag) {
  const parts = [];
  for (const it of $input.all()) {
    const c = it && it.json && it.json.document && it.json.document.pageContent;
    if (c && String(c).trim()) parts.push(String(c).trim());
  }
  ragChunks = parts.join('\n---\n').slice(0, 4000);
}

const HINTS = {
  auto_parts: 'перед точной ценой выясняй марку/модель/год/объём или VIN; предлагай аналоги дешевле оригинала.',
  wholesale: 'цена зависит от объёма партии — уточняй количество; предлагай отправить прайс.',
  flowers: 'уточняй дату, повод и бюджет; предлагай фото готовых букетов; напоминай про доставку.',
  kaspi_seller: 'рассрочка и оплата — всегда через оформление в магазине на Kaspi (рассрочка Kaspi у продавца ЕСТЬ — не отрицай её наличие); оплату в переписке не принимаем.',
  education: 'уточняй возраст и уровень; предлагай пробное занятие; веди к записи в группу/расписанию.',
