const j = $json;
const requestSeq = (j.requestSeq === undefined || j.requestSeq === null) ? 0 : j.requestSeq;
if (j.invalid || !j.ok) {
  return [{ json: { v: 1, requestSeq, suggestions: [], error: 'generation_failed' } }];
}
if (j.abstain) {
